import fs from 'node:fs';import cp from 'node:child_process';import path from 'node:path';import assert from 'node:assert/strict';import{createHash}from'node:crypto';
const [repo,out]=process.argv.slice(2),sha=b=>createHash('sha256').update(b).digest('hex');
const blob=(pin,p)=>cp.execFileSync('git',['cat-file','blob',pin+':'+p],{cwd:repo,maxBuffer:32e6});
const specs=[['agency-policy-source-phase-successor-20261015','aeeac1f4f64a4d0639a5e9f826c76ebe55a56268','policy-source-phase.test.mjs',13],['agency-fixed-approval-policy-support-20261015','fee53465a85b6c8fa7ac059d225429022db7260a','fixed-approval-policy.test.mjs',8],['agency-off-native-text-count-successor-20261015','267e0b5b7b535d6eda4bb646ff54b93ad2ecbdda','text-count.test.mjs',8]];
const base=i=>'docs/healthroster-build/proposals/'+specs[i][0]+'/';
function seal(){return specs.map(([dir,pin],i)=>{const raw=blob(pin,base(i)+'REVIEW_MANIFEST.json'),m=JSON.parse(raw);for(const e of [...m.entries,{path:'REVIEW_MANIFEST.json'}]){const b=blob(pin,base(i)+e.path);assert.deepEqual(b,fs.readFileSync(path.join(repo,base(i),e.path)));if(e.sha256){assert.equal(b.length,e.bytes);assert.equal(sha(b),e.sha256);}}return{dir,commit:pin,files:m.entries.length+1,manifest_sha256:sha(raw)};});}
fs.mkdirSync(out,{recursive:true});const before=seal();let owners=0,hunks=0,pins=0;
const policy=JSON.parse(blob(specs[0][1],base(0)+'POLICY_SOURCE_PHASE_COMPLETE_REVERSES.json'));
for(const p of policy.pins){assert.equal(sha(blob(p.pin,p.path)),p.raw_sha256);pins++;}
for(const r of policy.reverses){let s=blob(specs[0][1],base(0)+r.output).toString();assert.equal(sha(s),r.after_sha256);for(const h of [...r.hunks].reverse()){assert.equal(s.split(h.after).length,2);s=s.replace(h.after,()=>h.before);hunks++;}const p=policy.pins.find(p=>p.raw_sha256===r.before_sha256);assert(p);assert.deepEqual(Buffer.from(s),blob(p.pin,p.path));owners++;}
const fixed=JSON.parse(blob(specs[1][1],base(1)+'FIXED_APPROVAL_COMPLETE_REVERSES.json'));
const parser=blob(specs[1][1],base(1)+'reference/pinned-source-parser.mjs');assert.equal(sha(parser),fixed.parser_sha256);assert.deepEqual(parser,blob(fixed.parser_pin,fixed.parser_path));
const {functionEvents}=await import('data:text/javascript;base64,'+parser.toString('base64'));
for(const r of fixed.reverses){const source=blob(r.pin,r.input);assert.equal(sha(source),r.raw_source_sha256);const functions=functionEvents(source.toString().replaceAll('\r\n','\n')).events.filter(e=>e.kind==='CREATE'&&e.id===r.id);assert.equal(functions.length,1);let s=blob(specs[1][1],base(1)+r.output).toString();assert.equal(sha(s),r.after_sha256);for(const h of [...r.hunks].reverse()){assert.equal(s.split(h.after).length,2);s=s.replace(h.after,()=>h.before);hunks++;}assert.equal(s,functions[0].definition);assert.equal(sha(s),r.before_sha256);owners++;pins++;}
const codec=JSON.parse(blob(specs[2][1],base(2)+'FULL_REVERSE.json'));let s=blob(specs[2][1],base(2)+'runtime/off-rule-native-proxy.mjs').toString();assert.equal(sha(s),codec.after_sha256);for(const h of [...codec.hunks].reverse()){assert.equal(s.split(h.after).length,2);s=s.replace(h.after,()=>h.before);hunks++;}assert.deepEqual(Buffer.from(s),blob(codec.pin,codec.input));assert.equal(sha(s),codec.before_sha256);owners++;pins++;
assert.equal(owners,6);assert.equal(hunks,14);
const finalRoot=blob('f8c7830b22805339b205afe74fe3fc163f96381c','docs/healthroster-build/proposals/a0-source-raw-final-registration-20261015/01_source_final_before.sqlinc').toString();
const finalAgency=blob(specs[0][1],base(0)+'103_complete_active_source_guard_with_native_policy_union.sqlinc').toString();
for(const side of ['old','new']){assert(finalRoot.includes("source_revision_tokens_v1('public.'||tg_table_name,to_jsonb("+side+"))\n   ||private.timesheet_correction_a0_source_policy_tokens_v1('public.'||tg_table_name,to_jsonb("+side+'))'));assert(finalAgency.includes('source_revision_tokens_v1(p_relation,p_'+side+')\n  ||private.timesheet_correction_a0_source_policy_tokens_v1(p_relation,p_'+side+')'));}
assert(finalRoot.indexOf('fence_acquire_v1(nested_tokens,false)')<finalRoot.indexOf('perform private.weekly_source_agency_active_source_mutation_assert_v1'));
const tests=[];for(const [i,spec]of specs.entries()){const file=base(i)+spec[2],r=cp.spawnSync(process.execPath,['--test','--test-reporter=tap',file],{cwd:repo,encoding:'utf8',maxBuffer:8e6});const output=Buffer.from(r.stdout+r.stderr);fs.writeFileSync(path.join(out,spec[2]+'.tap.txt'),output);assert.equal(r.status,0);assert.match(output.toString(),new RegExp('# pass '+spec[3]+'\\b'));assert.match(output.toString(),/# fail 0\b/);tests.push({file,cases:spec[3],output_sha256:sha(output)});}
const checks={source_only:true,native:false,mount_ready:false,before,after:seal(),whole_owner_reverses:owners,unique_hunks:hunks,actual_input_pins:pins,tests,actual_raw_nested_union_order_matches_final_before:true,unrun:['complete current owner/role/registry/contract union','native current financial and API/Office/application acceptance','preset apply/clear and native weekly transition/finalise/document consumers remain engineering']};fs.writeFileSync(path.join(out,'CHECKS.json'),JSON.stringify(checks,null,2)+'\n');console.log(JSON.stringify(checks));
